from __future__ import annotations

import base64
import gzip
import subprocess
import sys
from pathlib import Path

PATCH_B64 = """"""

patch = gzip.decompress(base64.b64decode(PATCH_B64))
check = subprocess.run(["git", "apply", "--check", "-"], input=patch)
if check.returncode == 0:
    subprocess.run(["git", "apply", "-"], input=patch, check=True)
else:
    activity = Path("app/src/main/java/com/simplereader/app/ui/ReaderActivity.kt")
    layout = Path("app/src/main/res/layout/activity_reader.xml")
    expected = (
        activity.exists()
        and "private fun buildPagedWindow" in activity.read_text(encoding="utf-8")
        and layout.exists()
        and "com.simplereader.app.ui.PagedReaderView" in layout.read_text(encoding="utf-8")
    )
    if not expected:
        print("v587 patch could not be applied and expected materialized files are missing", file=sys.stderr)
        sys.exit(check.returncode)

print("v587 paged reader source materialized")
